class MGTopK { constructor(k){ this.k=k; this.counters=new Map(); }
  offer(x){ // update logic...
    for (let [v,c] of this.counters){ if (v===x){ this.counters.set(v,c+1); return; } }
    if (this.counters.size < this.k){ this.counters.set(x,1); return; }
    for (let v of Array.from(this.counters.keys())) this.counters.set(v, this.counters.get(v)-1);
    for (let [v,c] of Array.from(this.counters)) if (c<=0) this.counters.delete(v);
  }
  topK(){ return Array.from(this.counters.entries()).sort((a,b)=>b[1]-a[1]).slice(0,this.k); }
}}
```

